{
 "$schema": "https://json-schema.org/draft/2020-12/schema",
 "$id": "semantic-schema-core/semantic-abstract-schema@v1",
 "title": "Semantic Abstract Schema v1 の本体",
 "description": "Semantic Concrete Schema が従う契約の版 v1。Concrete は $schema にこの $id を書いて、使う版を示す。中身は Concrete が決め、Concrete が足す x- は x-definitions に作法どおりに定義する。Core 自身の x- の形は annotations が持つ。基盤はこの契約と作法だけを読む。",
 "x-prompt": {
  "read": {
   "means": "Concrete を書く人が従う契約で、従っていれば基盤が中身を知らずに使える。",
   "when": "Concrete を書く前と、Concrete を照らした指摘を直すときに読む。"
  },
  "write": [
   {
    "id": "declare-version",
    "rule": "根の $schema に、Abstract の版の $id（semantic-schema-core/semantic-abstract-schema@v1）を書く。",
    "why": "基盤は $schema で版を判定し、その版の契約で検査する。一覧に無い $schema は取りに行かずに断る。",
    "test": "根の $schema が、閉じた一覧の $id のどれかと同じかを見る。"
   },
   {
    "id": "name-and-description",
    "rule": "スキーマに title と description を書く。",
    "why": "Concrete を照らすときと描画が、スキーマの名前と説明を読む。",
    "test": "根に title と description があるかを見る。"
   },
   {
    "id": "generates-kind",
    "rule": "インスタンスを作るスキーマには x-generates を書き、根の properties に kind（const）を置く。",
    "why": "基盤は kind でインスタンスの種類を判定し、描画のしかたを選ぶ。",
    "test": "x-generates を持つスキーマの根に、kind の const があるかを見る。"
   },
   {
    "id": "generates-schema-name",
    "rule": "インスタンスを作るスキーマは、根の properties に $schema を置き、const にこのスキーマの $id を書く。",
    "why": "インスタンスの $schema に、このスキーマの名前以外が書かれるのを、書いたその場で止める。",
    "test": "properties.$schema.const が $id と同じかを見る。"
   },
   {
    "id": "prompt-per-unit",
    "rule": "書く単位（最上位のプロパティと、$defs の各形のプロパティ）ごとに description と x-prompt を書く。",
    "why": "Scaffold は、書く単位ごとの x-prompt を返す。",
    "test": "Concrete を照らした指摘が0件かを見る。"
   },
   {
    "id": "no-prompt-on-leaf",
    "rule": "入れ子の奥の葉には x-prompt を書かない。",
    "why": "親の x-prompt が葉まで案内するので、葉にも書くと同じ決まりが2か所に並ぶ。",
    "test": "x-prompt を持つ葉の親が、同じ決まりを持っていないかを見る。",
    "bad": "verification.passed[].option に x-prompt を書く。",
    "good": "verification.passed の x-prompt に、option の書き方も書く。"
   },
   {
    "id": "list-as-array",
    "rule": "並びになる値は、文字列に詰めず配列の型にする。",
    "why": "型で配列にしておけば、インスタンスを書く人が文字列に詰めることができない。",
    "test": "区切りの記号で並びを書かせる文字列の欄が無いかを見る。"
   },
   {
    "id": "declare-extensions",
    "rule": "Concrete が足す x- は、根の x-definitions に、値の形 ・ 意味 ・ 任せる検証役の名前を書く。",
    "why": "基盤は x- の意味を解釈せず、作法に従っているかだけを見て、宣言された検証役に任せる。",
    "test": "x- で始まるキーが、Core の x- か x-definitions にあるかを見る。"
   },
   {
    "id": "term-by-ref",
    "rule": "欄が glossary の term を指すときは、標準の $ref で glossary の $anchor を指す。",
    "why": "Semantic Schema Resolver は、$ref の指す先から欄の term を静的にたどる。",
    "test": "term を指す $ref の先が、閉じた一覧の glossary の $anchor かを見る。"
   },
   {
    "id": "rule-validator",
    "rule": "意味の判断が要る決まりには、by ・ requires ・ required を書く。Concrete が足した x- の検証は verifier に任せる。",
    "why": "基盤は by で validator を選び、verifier なら宣言された検証役を呼ぶ。",
    "test": "test を確かめるのに意味の判断が要る決まりに、by があるかを見る。"
   }
  ]
 },
 "type": "object",
 "required": [
  "$schema",
  "title",
  "description"
 ],
 "properties": {
  "$schema": {
   "enum": [
    "semantic-schema-core/semantic-abstract-schema@v1"
   ],
   "description": "従う Abstract の版",
   "x-prompt": {
    "read": {
     "means": "このスキーマが従う Abstract の版で、閉じた一覧のどれかである。"
    },
    "write": [
     {
      "id": "closed-list",
      "rule": "Abstract の版の $id を書く。",
      "why": "基盤は閉じた一覧に無い $schema を取りに行かずに断る。",
      "test": "値が閉じた一覧のどれかと同じかを見る。"
     }
    ]
   }
  },
  "$id": {
   "type": "string",
   "pattern": "^[a-z0-9][a-z0-9-]*/[a-z0-9][a-z0-9-]*@v[0-9]+$",
   "description": "スキーマの名前",
   "x-prompt": {
    "read": {
     "means": "インスタンスが $schema で指す、このスキーマの名前である。",
     "parse": "<Skill か Agent の名前>/<種類>@<版> の形で、版は v と数字である。"
    },
    "write": [
     {
      "id": "context-kind-version",
      "rule": "<Skill か Agent の名前>/<種類>@<版> の形で書く。",
      "why": "Semantic Schema Resolver は、Skill と Agent の置き場所から、この名前でスキーマを引く。",
      "test": "頭が、このスキーマを持つ Skill か Agent のフォルダの名前かを見る。"
     },
     {
      "id": "never-reuse",
      "rule": "公開した版の中身を変えるときは、版を上げた新しい名前で足す。",
      "why": "同じ名前で中身が変わると、前に書いたインスタンスが別のスキーマで検査される。",
      "test": "公開した版の名前の中身が、公開した時と同じかを見る。"
     }
    ]
   }
  },
  "title": {
   "type": "string",
   "minLength": 1,
   "description": "スキーマの名前",
   "x-prompt": {
    "read": {
     "means": "このスキーマが表すものの名前である。",
     "shown": "描画したページの題と、Concrete を照らした結果に出る。"
    },
    "write": [
     {
      "id": "noun",
      "rule": "インスタンスが何であるかを、名詞で書く。",
      "why": "読む人は題だけで、何のインスタンスかを判断する。",
      "test": "題が名詞で終わっているかを見る。",
      "bad": "意思決定を記録するためのもの",
      "good": "意思決定の記録"
     }
    ]
   }
  },
  "description": {
   "type": "string",
   "minLength": 1,
   "description": "スキーマの説明",
   "x-prompt": {
    "read": {
     "means": "インスタンスが何で、何を書かないかの説明である。"
    },
    "write": [
     {
      "id": "what-and-not",
      "rule": "インスタンスが何であるかと、書かないもの（ほかのスキーマが持つもの）を書く。",
      "why": "書かないものが分からないと、ほかのスキーマと同じことを2か所に書く。",
      "test": "説明に、書かないものが1つ以上あるかを見る。"
     }
    ]
   }
  },
  "x-generates": {
   "type": "string",
   "minLength": 1,
   "description": "このスキーマが作るインスタンスの置き場所",
   "x-prompt": {
    "read": {
     "means": "このスキーマのインスタンスが作られる置き場所である。",
     "parse": "<…> の部分は、番号や名前が入る場所である。"
    },
    "write": [
     {
      "id": "placeholder",
      "rule": "番号や名前の部分を <…> にして、インスタンスのファイルの置き場所を書く。",
      "why": "読む人とツールが、同じ置き場所に作る。",
      "test": "<…> 以外の部分が、実際の置き場所と同じかを見る。"
     },
     {
      "id": "only-for-instances",
      "rule": "インスタンスを作らない部品のスキーマには書かない。",
      "why": "書くと、作られないインスタンスの kind を探すことになる。",
      "test": "$defs だけを持つスキーマに x-generates が無いかを見る。"
     }
    ]
   }
  },
  "x-definitions": {
   "type": "object",
   "description": "Concrete が足す x- の定義（作法の1）",
   "propertyNames": {
    "pattern": "^x-[a-z0-9-]+$",
    "not": {
     "enum": [
      "x-prompt",
      "x-view",
      "x-relationship",
      "x-derive",
      "x-generates",
      "x-states",
      "x-definitions"
     ]
    }
   },
   "additionalProperties": {
    "type": "object",
    "required": [
     "schema",
     "description",
     "x-prompt",
     "verifier"
    ],
    "additionalProperties": false,
    "properties": {
     "schema": {
      "type": "object",
      "description": "x- の値の形（JSON Schema）"
     },
     "description": {
      "type": "string",
      "minLength": 1
     },
     "x-prompt": {
      "$ref": "#/$defs/prompt"
     },
     "verifier": {
      "type": "string",
      "minLength": 1,
      "description": "任せる検証役の名前（x- の定義に書く）"
     }
    }
   },
   "x-prompt": {
    "read": {
     "means": "このスキーマが足した x- の、値の形 ・ 意味 ・ 任せる検証役である。"
    },
    "write": [
     {
      "id": "no-core-names",
      "rule": "Core の x- と同じ名前を使わない。",
      "why": "Core の x- とぶつかると、どちらの意味で読むかが決まらない。",
      "test": "名前が Core の x- と重なっていないかを見る。"
     }
    ]
   }
  },
  "x-prompt": {
   "$ref": "#/$defs/prompt"
  },
  "properties": {
   "$ref": "#/$defs/fields"
  },
  "$defs": {
   "type": "object",
   "additionalProperties": {
    "$ref": "#/$defs/shape"
   }
  }
 },
 "if": {
  "required": [
   "x-generates"
  ]
 },
 "then": {
  "required": [
   "properties",
   "$id"
  ],
  "properties": {
   "properties": {
    "required": [
     "kind",
     "$schema"
    ],
    "properties": {
     "kind": {
      "required": [
       "const"
      ]
     },
     "$schema": {
      "required": [
       "const"
      ]
     }
    }
   }
  }
 },
 "$defs": {
  "shape": {
   "type": "object",
   "description": "$defs の形1つ。プロパティを持つなら、その書く単位に説明と案内を求める",
   "properties": {
    "properties": {
     "$ref": "#/$defs/fields"
    }
   }
  },
  "fields": {
   "type": "object",
   "description": "書く単位の並び",
   "properties": {
    "$schema": true
   },
   "additionalProperties": {
    "$ref": "#/$defs/field"
   }
  },
  "field": {
   "type": "object",
   "description": "書く単位1つ。x-relationship の形は annotations が、x-derive と x-view の形は本体の $defs が持つ",
   "required": [
    "description",
    "x-prompt"
   ],
   "properties": {
    "description": {
     "type": "string",
     "minLength": 1
    },
    "x-prompt": {
     "$ref": "#/$defs/prompt"
    },
    "x-relationship": {
     "$ref": "semantic-schema-core/annotations@v1#/$defs/relationship"
    },
    "x-derive": {
     "$ref": "#/$defs/derive"
    },
    "x-view": {
     "$ref": "#/$defs/view"
    }
   }
  },
  "derive": {
   "type": "object",
   "description": "x-derive。ほかの欄から決まる値の宣言。形は作法の1と一緒にこの論点で詰める"
  },
  "view": {
   "type": "object",
   "description": "x-view。ページテンプレート ・ カタログ ・ デザインシステムの参照と label。形は作法の1と一緒にこの論点で詰める"
  },
  "prompt": {
   "type": "object",
   "description": "x-prompt。read は値の読み方を観点ごとに、write は書くときの決まりを1件ずつ持つ",
   "required": [
    "read",
    "write"
   ],
   "additionalProperties": false,
   "properties": {
    "read": {
     "$ref": "#/$defs/reading"
    },
    "write": {
     "type": "array",
     "minItems": 1,
     "items": {
      "$ref": "#/$defs/rule"
     }
    }
   }
  },
  "reading": {
   "type": "object",
   "description": "値の読み方。観点ごとに1文",
   "required": [
    "means"
   ],
   "additionalProperties": false,
   "properties": {
    "means": {
     "$ref": "#/$defs/sentence",
     "description": "何を表すか"
    },
    "shown": {
     "$ref": "#/$defs/sentence",
     "description": "どこにどう出るか"
    },
    "parse": {
     "$ref": "#/$defs/sentence",
     "description": "値をどう解くか"
    },
    "when": {
     "$ref": "#/$defs/sentence",
     "description": "いつ、何のために読むか"
    }
   }
  },
  "rule": {
   "type": "object",
   "description": "書くときの決まり1件",
   "required": [
    "id",
    "rule",
    "why",
    "test"
   ],
   "additionalProperties": false,
   "properties": {
    "id": {
     "type": "string",
     "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
    },
    "rule": {
     "$ref": "#/$defs/sentence"
    },
    "why": {
     "$ref": "#/$defs/sentence"
    },
    "test": {
     "$ref": "#/$defs/sentence"
    },
    "by": {
     "enum": [
      "engine",
      "check",
      "ai",
      "human",
      "verifier"
     ],
     "description": "この決まりを検証する validator"
    },
    "requires": {
     "type": "array",
     "items": {
      "type": "string",
      "minLength": 1
     },
     "description": "validator に必要な capability"
    },
    "required": {
     "type": "boolean",
     "description": "検証できなければ全体を成功にしない決まりか"
    },
    "bad": {
     "type": "string",
     "minLength": 1
    },
    "good": {
     "type": "string",
     "minLength": 1
    }
   },
   "dependentRequired": {
    "bad": [
     "good"
    ],
    "good": [
     "bad"
    ]
   }
  },
  "sentence": {
   "type": "string",
   "minLength": 1,
   "maxLength": 120
  }
 }
}
